/bin/zsh -lc "python -m pytest -q; python - <<'PY'
from app import chunks
assert chunks([], 2) == []
assert chunks([1], 2) == [[1]]
assert chunks([1, 2, 3, 4], 2) == [[1, 2], [3, 4]]
for values in ([], [1]):
    for size in (0, -1):
        try:
            chunks(values, size)
        except ValueError as exc:
            assert str(exc) == 'size must be positive'
        else:
            raise AssertionError('Expected ValueError')
print('Empty-input, short-input, exact-chunk, and size-validation checks passed.')
PY
 git diff --check"

